{
  "story": "Gradient descent minimizes loss by shifting parameters against the slope. Each step reduces the error until convergence at the minimum.",
  "aha": {
    "stateId": "step3",
    "observation": "At the minimum, the gradient approaches zero and updates cease."
  },
  "layout": {
    "preset": "stepper-states",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "pic",
      "kind": "fixed-picture",
      "bind": {
        "active": "inputs.stepIndex",
        "regions": "variant.regions",
        "reason": "variant.states.why"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "variant.states.why",
        "target": "variant.states.calloutRegion",
        "text": "variant.states.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "variant.states.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Step",
      "options": ["Init", "Step 1", "Step 2", "Converged"]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset",
      "options": []
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Gradient Descent Overview",
        "regions": [
          {
            "id": "param",
            "label": "Parameter",
            "kind": "box",
            "values": ["x = 4.0"]
          },
          {
            "id": "loss",
            "label": "Loss Value",
            "kind": "box",
            "values": ["L = 16.0"]
          }
        ],
        "states": [
          {
            "id": "step0",
            "label": "Start",
            "short": "Init",
            "sentence": "Initialize parameter at an arbitrary high point.",
            "why": "Starting point on the loss curve.",
            "calloutRegion": "param",
            "readouts": [
              {
                "id": "r1",
                "label": "Parameter x",
                "value": "4.0"
              },
              {
                "id": "r2",
                "label": "Loss",
                "value": "16.0"
              }
            ]
          },
          {
            "id": "step1",
            "label": "First Descent",
            "short": "Step 1",
            "sentence": "Compute gradient and take a step downhill.",
            "why": "Steep slope yields a large parameter update.",
            "calloutRegion": "param",
            "readouts": [
              {
                "id": "r1",
                "label": "Parameter x",
                "value": "2.0"
              },
              {
                "id": "r2",
                "label": "Loss",
                "value": "4.0"
              }
            ]
          },
          {
            "id": "step2",
            "label": "Second Descent",
            "short": "Step 2",
            "sentence": "Continue stepping towards the minimum.",
            "why": "Slope flattens, reducing update magnitude.",
            "calloutRegion": "param",
            "readouts": [
              {
                "id": "r1",
                "label": "Parameter x",
                "value": "0.5"
              },
              {
                "id": "r2",
                "label": "Loss",
                "value": "0.25"
              }
            ]
          },
          {
            "id": "step3",
            "label": "Convergence",
            "short": "Done",
            "sentence": "Gradient is zero; loss is at its global minimum.",
            "why": "No further updates occur.",
            "calloutRegion": "loss",
            "readouts": [
              {
                "id": "r1",
                "label": "Parameter x",
                "value": "0.0"
              },
              {
                "id": "r2",
                "label": "Loss",
                "value": "0.0"
              }
            ]
          }
        ]
      }
    ]
  }
}
